// The keys of an application environment's signed tokens: generated by the first deploy of a contract with a token
// purpose, sealed in the vault, rotated only when an operator asks and then applied by the next deploy, and a retired key
// kept verifying until the last token it signed may expire.

import type { ContractArtifact, SchemaShape } from '@fabrika/auth-core'
import { describe, expect, test } from 'bun:test'
import { notesArtifact } from '../../../auth-core/src/__tests__/fixtures/notes-artifact'
import { tokenKeyPurpose, VaultTokenKeys } from '../token-keys'
import { Vault } from '../vault'
import { createHarness, queryRows } from './helpers/harness'

const KEY = btoa(String.fromCharCode(...new Uint8Array(32).fill(7)))
const T0 = 1_800_000_000
const DAY = 86_400
const claims: SchemaShape = { type: 'object', fields: { email: { type: 'boolean' } } }

const withTokens = (maxDays: number): ContractArtifact => ({ ...notesArtifact, tokens: { unsubscribe: { claims, maxDays } } })

async function setup() {
	const harness = createHarness()
	const { registry, tokenKeys } = harness.repositories
	await registry.createApp({ id: 'notes', repoUrl: 'github.com/acme/notes' })
	await registry.upsertAppEnv({
		appId: 'notes',
		env: 'prod',
		namespaceId: null,
		provider: 'test',
		providerTargetJson: '{}',
		providerArtifactJson: '{}',
	})
	const vault = await Vault.create(harness.d1, KEY)
	const clock = { now: T0 }
	const keys = new VaultTokenKeys(tokenKeys, () => Promise.resolve(vault), () => clock.now)
	return { harness, clock, keys, records: tokenKeys }
}

const ids = (value: string | null): string[] => (value ?? '').split(',').filter((entry) => entry !== '').map((entry) => entry.split(':')[0] ?? '')

describe('VaultTokenKeys', () => {
	test('a contract without token purposes gets no key and no variable', async () => {
		const { keys, harness } = await setup()
		expect(await keys.reconcile('notes', 'prod', notesArtifact)).toBeNull()
		expect(queryRows(harness.sqlite, 'SELECT * FROM app_env_token_keys')).toEqual([])
	})

	test('the first deploy generates one signing key, sealed in the vault, and later deploys hand the same one', async () => {
		const { keys, harness } = await setup()
		const first = await keys.reconcile('notes', 'prod', withTokens(400))
		expect(first).toMatch(/^[A-Za-z0-9_-]{11}:[A-Za-z0-9_-]{43}$/)
		expect(await keys.reconcile('notes', 'prod', withTokens(400))).toBe(first)
		const [id] = ids(first)
		expect(queryRows(harness.sqlite, 'SELECT label FROM vault').map((row) => row['label'])).toEqual([
			tokenKeyPurpose('notes', 'prod', id ?? '').label,
		])
		// The secret is sealed: the vault row holds no plaintext of it.
		expect(JSON.stringify(queryRows(harness.sqlite, 'SELECT * FROM vault'))).not.toContain((first ?? '').split(':')[1])
	})

	test('a requested rotation signs with a new key, and the retired one verifies until its longest token may expire', async () => {
		const { keys, records, clock } = await setup()
		const [old] = ids(await keys.reconcile('notes', 'prod', withTokens(400)))
		expect(await records.requestRotation('notes', 'prod', T0)).toBe(true)
		clock.now = T0 + 10 * DAY
		const rotated = ids(await keys.reconcile('notes', 'prod', withTokens(30)))
		expect(rotated).toHaveLength(2)
		expect(rotated[1]).toBe(old)
		// A shorter maxDays after the key signed cannot cut off the 400-day tokens it signed.
		clock.now = T0 + 10 * DAY + 399 * DAY
		expect(ids(await keys.reconcile('notes', 'prod', withTokens(30)))).toEqual(rotated)
		clock.now = T0 + 10 * DAY + 400 * DAY
		expect(ids(await keys.reconcile('notes', 'prod', withTokens(30)))).toEqual([rotated[0]])
	})

	test("a longer maxDays raises the signing key's lifetime; nothing rotates without a request", async () => {
		const { keys, records, clock } = await setup()
		const first = await keys.reconcile('notes', 'prod', withTokens(30))
		expect(await keys.reconcile('notes', 'prod', withTokens(90))).toBe(first)
		expect((await records.list('notes', 'prod'))[0]?.max_days).toBe(90)
		expect(await keys.reconcile('notes', 'prod', withTokens(10))).toBe(first)
		expect((await records.list('notes', 'prod'))[0]?.max_days).toBe(90)
		clock.now = T0 + 1000 * DAY
		expect(await keys.reconcile('notes', 'prod', withTokens(10))).toBe(first)
	})

	test('a rotation request without a key records nothing', async () => {
		const { records } = await setup()
		expect(await records.requestRotation('notes', 'prod', T0)).toBe(false)
	})
})
